  const summary = { id, sourceId, started, completed: new Date().toISOString(), ...result, forcedStop,
    client: 'Codex CLI 0.155.0-alpha.9.2', modelRequested: 'gpt-6-astra',
    modelResolved: 'not attested by JSONL event format; requested model recorded',
    eventTypes: events.map(e => e.type), toolEvents: toolEvents.map(e => ({ type: e.type, itemType: e.item?.type })),
    usage: events.filter(e => e.usage).map(e => e.usage),
    structural, semanticReview: 'PENDING', stderrBytes: Buffer.byteLength(stderr),
    stdoutSha256: hash(stdout), stderrSha256: hash(stderr),
    explanationSha256: fs.existsSync(output) ? hash(read(`${id}.explanation.json`)) : null };
  write(`${id}.result.json`, json(summary));
  console.log(json(summary));
  if (result.code !== 0 || forcedStop || toolEvents.length || structural?.structuralChecks !== 'PASSED') process.exitCode = 1;
