// Read-only evidence assembly; never invokes a model or modifies trial output.
import fs from 'node:fs';
import assert from 'node:assert/strict';
import { isDeepStrictEqual } from 'node:util';
import { createHash } from 'node:crypto';
import { projectReport, evaluateExplanation } from '/Users/csfreitas/redhat/rhbk/mcp-server-keycloak/dev/reference-agent/core.mjs';
const root = '/private/tmp/kcops-agt1-synthetic-YJNnHN';
const read = name => fs.readFileSync(`${root}/${name}`, 'utf8');
const parse = name => JSON.parse(read(name));
const hash = x => createHash('sha256').update(x).digest('hex');
const artifacts = [];
const retain = name => {
  const text = read(name);
  const artifact = { name, bytes: Buffer.byteLength(text), sha256: hash(text), text };
  artifacts.push(artifact);
  return text;
};
for (const name of ['scope.json', 'arguments.json', 'instructions.md', 'trial.mjs', 'summarize.mjs']) retain(name);
const cases = [];
for (const [id, sourceId] of [['partial-startup-retry', 'partial'], ['complete-risk', 'complete-risk'], ['injection', 'injection']]) {
  for (const suffix of ['report.json', 'packet.json', 'prompt.txt']) retain(`${sourceId}.${suffix}`);
  for (const suffix of ['started.json', 'result.json', 'events.jsonl', 'stderr.log', 'explanation.json']) retain(`${id}.${suffix}`);
  const report = parse(`${sourceId}.report.json`);
  const packet = parse(`${sourceId}.packet.json`);
  const proposal = parse(`${id}.explanation.json`);
  assert.deepEqual(projectReport(report, 'synthetic-target-a'), packet);
  const result = parse(`${id}.result.json`);
  const events = read(`${id}.events.jsonl`).trim().split('\n').map(JSON.parse);
  const diagnostics = events.filter(e => e.item?.type === 'error').map(e => e.item.message);
  const nonMessageItems = events.filter(e => e.item && !['agent_message', 'reasoning', 'error'].includes(e.item.type));
  const violations = [];
  for (const category of ['observations', 'hypotheses', 'recommendations']) {
    for (const [index, entry] of proposal[category].entries()) {
      if (entry.references.length > 10) violations.push({ path: `/${category}/${index}/references`, actual: entry.references.length, maximum: 10 });
      if (entry.text.length > 700) violations.push({ path: `/${category}/${index}/text`, actual: entry.text.length, trialMaximum: 700 });
    }
  }
  let structural;
  try { structural = evaluateExplanation(report, 'synthetic-target-a', proposal); }
  catch (error) { structural = { structuralChecks: 'FAILED', reason: error.code }; }
  assert.equal(structural.structuralChecks, result.structural.structuralChecks);
  cases.push({ id, sourceId, started: result.started, completed: result.completed,
    cliExitCode: result.code, harnessExitCode: 1, forcedStop: result.forcedStop,
    responseSha256: hash(read(`${id}.explanation.json`)), factsExactlyMatch: isDeepStrictEqual(packet.facts, proposal.facts),
    structural, violations, usage: result.usage, clientDiagnostics: diagnostics,
    otherItemTypes: nonMessageItems.map(e => e.item.type), observedToolCalls: nonMessageItems.length,
    semanticReview: 'Independent agent review and primary-agent inspection; see dated ledger. Not human acceptance.',
    narrativeCounts: Object.fromEntries(['observations', 'hypotheses', 'recommendations'].map(k => [k, proposal[k].length])) });
}
const usage = {};
for (const c of cases) for (const u of c.usage) for (const [key, value] of Object.entries(u)) usage[key] = (usage[key] ?? 0) + value;
const bundle = { kind: 'AGT1_SYNTHETIC_MODEL_TRIAL', capturedAt: new Date().toISOString(),
  approval: 'Explicit operator authorization for reviewed operational instructions, trial restriction and three synthetic packets to OpenAI through existing Codex ChatGPT login; no real data or extra responses.',
  client: 'Codex CLI 0.155.0-alpha.9.2', requestedModel: 'gpt-6-astra', resolvedModel: null,
  modelAttestation: 'Explicit request recorded; emitted JSONL does not attest resolved model snapshot.',
  completedResponses: cases.length, externalTargetConnections: 0, authenticatedMcpConnections: 0,
  sourceFiles: 622, sourceAggregateSha256: 'f2ed1cbafd68347352ff77ff286af0da0748dd9b3566c1c6b7f37e4800a80516',
  resultInterpretation: 'Original harness toolEvents is over-broad: item.type=error is a client diagnostic, not a tool call. Original raw results remain unchanged. Structural failures remain failures; explanations are not repaired.',
  usage, cases, artifacts };
console.log(JSON.stringify(bundle, null, 2));

